-- vavang — chargement du jeu de démonstration (généré par tests/generer-seed.mjs le 2026-11-19, ne pas modifier à la main).
-- À exécuter d'un bloc dans l'éditeur SQL, APRÈS schema.sql et schema_demo.sql. Rejouable.
-- Organisme fictif : Communauté d'agglomération de démonstration. Mot de passe des 6 comptes partagés : public par nature (affiché sur la page d'accueil).
-- Les pièces de supabase/seed/fichiers/ sont à déposer à part dans le compartiment « pieces », aux mêmes chemins (text/plain;charset=utf-8).

-- 1. Comptes Auth à UUID fixes (colonnes de jetons à '' et jamais NULL)
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current, reauthentication_token)
select '00000000-0000-0000-0000-000000000000', c.id, 'authenticated', 'authenticated', c.email, extensions.crypt('Demonstration-2026', extensions.gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', '', '', ''
from (values
  ('00000000-0000-4000-a000-000000000001'::uuid, 'admin@demo.example'),
  ('00000000-0000-4000-a000-000000000002'::uuid, 'gestionnaire@demo.example'),
  ('00000000-0000-4000-a000-000000000003'::uuid, 'prescripteur@demo.example'),
  ('00000000-0000-4000-a000-000000000004'::uuid, 'valideur@demo.example'),
  ('00000000-0000-4000-a000-000000000005'::uuid, 'lecteur@demo.example'),
  ('00000000-0000-4000-a000-000000000006'::uuid, 'support@demo.example')) c(id, email)
on conflict (id) do nothing;
-- la colonne email de auth.identities est générée : ne pas l'insérer
insert into auth.identities (user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
select u.id, u.id::text, 'email', jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true), now(), now(), now()
from auth.users u where u.id::text like '00000000-0000-4000-a000-00000000000_'
on conflict (provider_id, provider) do nothing;

-- 2. Jeu de référence
delete from public.demo_seed;
insert into public.demo_seed (table_nom, id, d, cree_le)
select t.key, e->>'id', e - 'id', coalesce(case when e->>'cree_le' ~ '^\d{4}-\d{2}-\d{2}' then (e->>'cree_le')::timestamptz end, case when e->>'date_creation' ~ '^\d{4}-\d{2}-\d{2}' then (e->>'date_creation')::timestamptz end, case when e->>'date' ~ '^\d{4}-\d{2}-\d{2}' then (e->>'date')::timestamptz end, case when e->>'date_depot' ~ '^\d{4}-\d{2}-\d{2}' then (e->>'date_depot')::timestamptz end, now())
from jsonb_each($seed${"profils":[{"id":"00000000-0000-4000-a000-000000000001","email":"admin@demo.example","nom":"Alix Fontaine","role":"administrateur","service":"Direction de la commande publique","actif":true},{"id":"00000000-0000-4000-a000-000000000002","email":"gestionnaire@demo.example","nom":"Camille Morel","role":"gestionnaire","service":"Direction de la commande publique","actif":true},{"id":"00000000-0000-4000-a000-000000000003","email":"prescripteur@demo.example","nom":"Sacha Leroy","role":"prescripteur","service":"Direction de l'environnement","actif":true},{"id":"00000000-0000-4000-a000-000000000004","email":"valideur@demo.example","nom":"Dominique Vidal","role":"valideur","service":"Direction de la commande publique","actif":true},{"id":"00000000-0000-4000-a000-000000000005","email":"lecteur@demo.example","nom":"Claude Besson","role":"lecteur","service":"Contrôle de gestion","actif":true},{"id":"00000000-0000-4000-a000-000000000006","email":"support@demo.example","nom":"Équipe support","role":"support","service":"l'entreprise.ai (éditeur)","actif":true}],"habilitations":[{"id":"administrateur|besoins.ecrire","role":"administrateur","droit":"besoins.ecrire"},{"id":"administrateur|besoins.valider","role":"administrateur","droit":"besoins.valider"},{"id":"administrateur|consultations.ecrire","role":"administrateur","droit":"consultations.ecrire"},{"id":"administrateur|consultations.toutes","role":"administrateur","droit":"consultations.toutes"},{"id":"administrateur|consultations.service","role":"administrateur","droit":"consultations.service"},{"id":"administrateur|dce.rediger","role":"administrateur","droit":"dce.rediger"},{"id":"administrateur|dce.relire","role":"administrateur","droit":"dce.relire"},{"id":"administrateur|dce.valider","role":"administrateur","droit":"dce.valider"},{"id":"administrateur|dce.publier","role":"administrateur","droit":"dce.publier"},{"id":"administrateur|analyse.parametrer","role":"administrateur","droit":"analyse.parametr