:"valideur","droit":"analyse.valider"},{"id":"valideur|rapport.valider","role":"valideur","droit":"rapport.valider"},{"id":"valideur|evaluations.valider","role":"valideur","droit":"evaluations.valider"},{"id":"valideur|journal.lire","role":"valideur","droit":"journal.lire"},{"id":"valideur|support.declarer","role":"valideur","droit":"support.declarer"},{"id":"lecteur|journal.lire","role":"lecteur","droit":"journal.lire"},{"id":"lecteur|support.declarer","role":"lecteur","droit":"support.declarer"},{"id":"support|support.traiter","role":"support","droit":"support.traiter"},{"id":"support|support.declarer","role":"support","droit":"support.declarer"}],"parametres":[{"id":"seuils","valeur":{"date_effet":"2026-01-01","dispense_fournitures_services":60000,"dispense_travaux":100000,"publicite_obligatoire":90000,"formalise_fournitures_services":216000,"formalise_travaux":5404000}},{"id":"demo_v2","valeur":true},{"id":"demo_v3","valeur":true},{"id":"demo_v4","valeur":true},{"id":"demo_v5","valeur":true},{"id":"demo_v6","valeur":true},{"id":"securite","valeur":{"inactivite_minutes":15,"echecs_max":5,"verrouillage_minutes":15,"mfa_admin":true,"mfa_tous":false,"mfa_proposer":true}},{"id":"circuit_dce","valeur":[{"id":"relecture","libelle":"Relecture","droit":"dce.relire"},{"id":"validation","libelle":"Validation","droit":"dce.valider"}]}],"tickets":[{"id":"tk1","numero":"T-2026-0001","date_creation":"2026-11-16T05:05:00.000Z","demandeur_id":"00000000-0000-4000-a000-000000000002","demandeur_nom":"Camille Morel","service":"Direction de la commande publique","objet":"Ajouter un modèle de lettre de rejet pour les marchés de travaux","criticite":"P4","description":"Nous souhaitons un modèle de lettre de rejet propre aux marchés de travaux, avec les mentions sur la sous-traitance.","statut":"resolu","echeances":{"prise_en_charge":"2026-11-17T05:05:00.000Z","diagnostic":null,"contournement":null,"retablissement":null},"intervenant_nom":"Équipe support","pris_en_charge_le":"2026-11-16T07:05:00.000Z","resolu_le":"2026-11-18T11:05:00.000Z","pieces_jointes":[],"historique":[{"date":"2026-11-16T05:05:00.000Z","auteur":"Camille Morel","type":"Création","texte":"Demande créée (P4)."},{"date":"2026-11-16T07:05:00.000Z","auteur":"Équipe support (support)","type":"Prise en charge","texte":"Demande de paramétrage prise en charge."},{"date":"2026-11-18T11:05:00.000Z","auteur":"Équipe support (support)","type":"Solution proposée","texte":"Modèle « Lettre de rejet — travaux » ajouté dans la bibliothèque des courriers. Merci de vérifier et de valider la clôture."}]}],"annonces":[{"id":"c-analyse","type":"carrousel","ordre":1,"theme":"sombre","surtitre":"Nouveau","titre":"L'analyse des offres, de la grille au rapport","texte":"Grille verrouillée, notes justifiées par un extrait, classement établi à partir des seules notes validées.","date_evenement":"","bouton":"En savoir plus","lien_rubrique":"r-analyser","actif":true,"image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"c-formation","type":"carrousel","ordre":2,"theme":"creme","surtitre":"Se former","titre":"Sessions de prise en main","texte":"Une demi-journée par profil, dans les locaux de la collectivité, avec des cas pratiques.","date_evenement":"Du 1er au 12 décembre 2026","bouton":"Voir le programme","lien_rubrique":"r-formations","actif":true,"image":"img/photos/maido-lever-du-soleil.jpg","credit":"Lever du soleil sur le Maïdo — photo Rémih, CC BY-SA 4.0","cadrage":"center 40%"},{"id":"c-recensement","type":"carrousel","ordre":3,"theme":"braise","surtitre":"Collectivité","titre":"Recensement des besoins 2027","texte":"Saisissez vos besoins de l'année prochaine pour permettre la computation des seuils.","date_evenement":"Avant le 15 janvier 2027","bouton":"Comment faire","lien_rubrique":"r-preparer","actif":true,"image":"img/photos/le-port-vue-du-ciel.jpg","credit":"Le Port vu du ciel — photo Ville du Port, CC BY-SA 4.0","cadrage":"center 55%"},{"id":"c-seuils","type":"carrousel","ordre":4,"theme":"sombre","surtitre":"S'informer","titre":"Seuils de procédure en vigueur","texte":"Les seuils appliqués par l'outil sont tenus à jour par la direction de la commande publique.","date_evenement":"","bouton":"Consulter","lien_rubrique":"r-seuils","actif":true,"image":"img/photos/mafate-depuis-le-grand-benare.jpg","credit":"Mafate depuis le Grand Bénare — photo Mamphi, CC BY-SA 3.0","cadrage":"center 40%"},{"id":"a-recensement","type":"actualite","source":"collectivite","date":"2026-11-18","titre":"Recensement des besoins 2027 ouvert","texte":"Les services prescripteurs saisissent leurs besoins jusqu'au 15 janvier.","contenu":"Le recensement des besoins de l'année 2027 est ouvert. Chaque service saisit ses besoins dans l'écran « Besoins et seuils ».\n\nLa direction de la commande publique arrêtera ensuite les procédures à partir de la computation des seuils.","actif":true},{"id":"a-ccap","type":"actualite","source":"collectivite","date":"2026-11-15","titre":"Nouveau modèle de CCAP « services courants »","texte":"Le modèle a été mis à jour par la direction de la commande publique.","contenu":"Un nouveau modèle de CCAP pour les services courants est disponible dans la bibliothèque des modèles. Il intègre une clause de révision des prix et une clause environnementale d'exécution.","actif":true},{"id":"a-permanence","type":"actualite","source":"collectivite","date":"2026-11-10","titre":"Permanence de la commande publique le jeudi matin","texte":"Les gestionnaires répondent aux questions des services prescripteurs.","contenu":"Chaque jeudi de 8 h 30 à 12 h, un gestionnaire de la direction de la commande publique répond aux questions des services prescripteurs sur leurs projets d'achat.","actif":true},{"id":"a-accueil","type":"actualite","source":"editeur","date":"2026-11-19","titre":"Nouveau : page d'accueil et annonces","texte":"Les informations utiles défilent dès la connexion ; l'administrateur les met à jour.","contenu":"La page d'accueil présente désormais les annonces de la collectivité, les actualités et les rubriques d'information. L'administrateur les publie depuis le menu « Page d'accueil et annonces ».","actif":true},{"id":"a-comparaison","type":"actualite","source":"editeur","date":"2026-11-13","titre":"Comparer les offres critère par critère","texte":"Une vue transversale affiche les réponses de tous les candidats sur le même critère.","contenu":"Dans l'onglet « Analyse », la vue « Par critère » affiche côte à côte les appréciations et les notes de tous les candidats pour un même critère, sans ajout de critère non prévu.","actif":true},{"id":"a-reprise","type":"actualite","source":"editeur","date":"2026-11-07","titre":"Reprendre vos tableaux de suivi existants","texte":"Reprise à blanc, rapport de contrôle, puis reprise définitive.","contenu":"Un tableau de suivi des marchés (XLSX, ODS ou CSV) peut être repris : l'outil propose une correspondance des colonnes, contrôle les données sans rien écrire, puis reprend les lignes valides. Un retour arrière reste possible.","actif":true},{"id":"r-preparer","type":"rubrique","onglet":"solutions","ordre":1,"titre":"Préparer le besoin sans rien oublier","resume":"Un tableur par service, des besoins éparpillés, un seuil franchi sans le voir. vavang additionne pour vous et vous dit quelle procédure s’impose.","contenu":"\nChaque année, c’est la même course. Les services envoient leurs besoins par courriel, chacun dans son format. Personne ne voit que trois achats de mobilier, mis bout à bout, dépassent le seuil de publicité.\n\n## Ce qui change\n- **Un formulaire unique** pour tous les services : objet, montant, durée, famille d’achat.\n- **Le cumul se fait tout seul**, par famille homogène et tous services confondus.\n- **La procédure s’affiche** à côté du montant cumulé, avec l’explication du seuil en jeu.\n\n## En trois gestes\n1. Le service prescripteur recense son besoin.\n2. La direction de la commande publique lit la computation des seuils.\n3. Elle arrête la procédure, la justifie, et crée la consultation en un clic.\n\n> La procédure suggérée reste une aide. Le choix final, et sa justification, reviennent à l’acheteur. Tout est tracé.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"r-dce","type":"rubrique","onglet":"solutions","ordre":2,"titre":"Un DCE prêt en une matinée, validé sans allers-retours","resume":"Les modèles se remplissent seuls, les clauses s’insèrent en un clic, et le circuit de validation suit le document jusqu’à la publication.","contenu":"\nRédiger un dossier de consultation, c’est souvent copier l’ancien, chercher les références à changer, puis attendre trois signatures par courriel.\n\n## Des modèles qui se remplissent\nLa référence, l’objet, les lots, la date limite et les critères de la grille sont repris dans le document. Il reste à écrire ce qui est propre au marché.\n\n## Une bibliothèque de clauses\nRévision des prix, clause environnementale, offres anormalement basses : les clauses validées par la direction s’insèrent là où se trouve le curseur.\n\n## Un circuit qui s’adapte à votre organisation\nRelecture, visa juridique, validation : c’est l’administrateur qui choisit les étapes et qui peut les approuver. Chaque passage est daté et signé.\n\n> Chaque enregistrement crée une version. On sait toujours qui a changé quoi, et quand.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"r-analyser","type":"rubrique","onglet":"solutions","ordre":3,"titre":"Analyser les offres : chaque note a sa preuve","resume":"Grille verrouillée avant l’ouverture des plis, note justifiée par un extrait du mémoire, classement établi à partir des seules notes validées.","contenu":"\nUne analyse se conteste rarement sur les chiffres. Elle se conteste sur la justification. vavang vous oblige à l’écrire au moment où vous notez.\n\n## Avant les plis : une grille figée\nCritères, sous-critères, pondérations, formule de prix, règle d’arrondi. L’outil vérifie que le total fait 100. Un valideur verrouille la grille : elle ne bouge plus.\n\n## Pendant : une note, une preuve\nVous sélectionnez la phrase du mémoire technique qui justifie la note. Elle est citée avec le nom du fichier et la page. **Une note sans justification ne peut pas être validée.**\n\n## Après : un classement que personne ne fabrique\n- Les montants sont validés par un agent habilité.\n- Chaque note est validée par un autre agent que celui qui l’a saisie.\n- Le classement provisoire ne retient que les notes validées.\n\n> L’outil signale les pièces manquantes et les prix anormalement bas. Il ne rejette rien, ne note rien, ne classe rien tout seul.","lecture_min":3,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"r-executer","type":"rubrique","onglet":"solutions","ordre":4,"titre":"Suivre l’exécution sans tableur à côté","resume":"Ordres de service, bons de commande, avenants, révisions de prix : tout est rattaché au marché, avec ses pièces et ses échéances.","contenu":"\nUn marché notifié, c’est le début du travail. Les bons de commande s’accumulent, un avenant passe, la reconduction arrive sans prévenir.\n\n## Tout sur une seule fiche\n- **Le montant actuel**, avenants compris.\n- **Le cumul des bons de commande**, comparé au montant maximum.\n- **La révision des prix calculée** : saisissez l’indice, vavang applique la formule du marché et arrondit le coefficient.\n\n## Les échéances qui remontent\nLa fin de période et la date de décision de reconduction s’affichent dans le tableau de bord, 120 jours avant.\n\n> Chaque événement garde sa pièce justificative : l’ordre de service, le bon de commande, l’avenant signé.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"r-piloter","type":"rubrique","onglet":"solutions","ordre":5,"titre":"Piloter l’activité d’un coup d’œil","resume":"Consultations en cours, validations en attente, échéances, alertes : le tableau de bord et les notifications vous disent quoi faire aujourd’hui.","contenu":"\nLe matin, une question : qu’est-ce qui m’attend ? vavang y répond en une page.\n\n## Le tableau de bord\nConsultations par étape, analyses à valider, marchés en cours, montant notifié, alertes à traiter.\n\n## Les notifications\nUne note renvoyée, une analyse à valider, un document à relire, une réponse du support : vous êtes prévenu dans l’application, avec le lien direct.\n\n## L’évaluation des titulaires\nDes critères définis par la collectivité, une note de 1 à 5, et toujours des faits vérifiables à l’appui.\n\n> Une évaluation n’exclut jamais automatiquement une entreprise. Elle sert à piloter, pas à sanctionner.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/fournaise-vue-du-ciel.jpg","credit":"Le Piton de la Fournaise vu du ciel — photo Pouyot, CC BY-SA 4.0","cadrage":"center 45%"},{"id":"r-formations","type":"rubrique","onglet":"se-former","ordre":1,"titre":"Prise en main : une demi-journée suffit","resume":"Des sessions courtes, par profil, dans vos locaux, sur vos propres dossiers. On repart en sachant faire, pas en ayant écouté.","contenu":"\nOn n’apprend pas un logiciel en regardant quelqu’un cliquer. Chaque session se passe sur le poste de l’agent, avec un dossier réel ou fictif.\n\n## Trois formats\n- **Administrateurs** : une journée. Comptes, habilitations, circuits, modèles, seuils, sécurité.\n- **Gestionnaires de marchés** : une journée. Du recensement du besoin au rapport d’analyse.\n- **Prescripteurs, valideurs, lecteurs** : une demi-journée. Les gestes de leur profil, rien de plus.\n\n## Comment ça se passe\n1. Présentation courte des écrans utiles.\n2. Démonstration sur un dossier complet.\n3. Cas pratiques, puis questions.\n4. Une évaluation rapide de ce qui est acquis.\n\n> Chaque participant repart avec une fiche pratique d’une page pour son profil.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/maido-lever-du-soleil.jpg","credit":"Lever du soleil sur le Maïdo — photo Rémih, CC BY-SA 4.0","cadrage":"center 35%"},{"id":"r-guides","type":"rubrique","onglet":"se-former","ordre":2,"titre":"Guides pas à pas","resume":"Les gestes courants, écran par écran, en moins de cinq minutes chacun.","contenu":"\nUn doute au moment d’agir ? Les guides répondent à une seule question à la fois.\n\n## Les plus consultés\n- Recenser un besoin et lire la computation des seuils.\n- Paramétrer et verrouiller une grille d’analyse.\n- Justifier une note par un extrait du mémoire technique.\n- Valider une analyse et générer le rapport.\n- Activer la double authentification.\n\n> Le guide utilisateur et le guide administrateur complets sont remis au format numérique, et tenus à jour à chaque version.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/maido-lever-du-soleil.jpg","credit":"Lever du soleil sur le Maïdo — photo Rémih, CC BY-SA 4.0","cadrage":"center 35%"},{"id":"r-faq","type":"rubrique","onglet":"se-former","ordre":3,"titre":"Questions fréquentes","resume":"Les réponses aux questions qu’on nous pose le plus.","contenu":"\n## Puis-je modifier une note validée ?\nNon. Un valideur doit d’abord la rouvrir. La réouverture est tracée au journal.\n\n## Qui peut verrouiller une grille ?\nLes profils habilités par l’administrateur, en général les valideurs.\n\n## J’ai oublié mon mot de passe.\nContactez l’administrateur de votre collectivité : il le réinitialise.\n\n## Mon compte est verrouillé.\nAprès cinq essais infructueux, le compte se bloque quinze minutes. L’administrateur peut le débloquer tout de suite.\n\n## J’ai changé de téléphone.\nDemandez à l’administrateur de réinitialiser votre double authentification, puis activez-la de nouveau.","lecture_min":2,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/maido-lever-du-soleil.jpg","credit":"Lever du soleil sur le Maïdo — photo Rémih, CC BY-SA 4.0","cadrage":"center 35%"},{"id":"r-seuils","type":"rubrique","onglet":"s-informer","ordre":1,"titre":"Seuils et procédures : ce que l’outil applique","resume":"Les seuils utilisés pour la computation sont tenus par la direction de la commande publique, avec leur date d’effet.","contenu":"\nLes seuils changent : seuils européens tous les deux ans, décrets nationaux entre-temps. vavang ne les fige pas.\n\n## Qui les tient à jour ?\nL’administrateur, depuis l’écran des paramètres. Chaque modification est datée, signée et tracée.\n\n## Où les voir ?\nUne fois connecté, dans « Besoins et seuils ». Les valeurs en vigueur s’affichent au-dessus de la computation.\n\n> L’aide au choix de la procédure s’appuie sur ces valeurs. Vérifiez-les à chaque évolution réglementaire.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/mafate-depuis-le-grand-benare.jpg","credit":"Mafate depuis le Grand Bénare — photo Mamphi, CC BY-SA 3.0","cadrage":"center 45%"},{"id":"r-veille","type":"rubrique","onglet":"s-informer","ordre":2,"titre":"Veille réglementaire","resume":"Ce qui change dans la commande publique, et ce que vavang adapte en conséquence.","contenu":"\nChaque évolution qui touche l’outil est annoncée ici, avant son entrée en vigueur.\n\n## Pour chaque évolution\n- La nature du changement et le texte concerné.\n- La date d’entrée en vigueur.\n- Ce qui change dans vavang, et la date de mise à disposition.\n\n> Les adaptations réglementaires font partie du service. Elles ne sont jamais facturées en plus.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/mafate-depuis-le-grand-benare.jpg","credit":"Mafate depuis le Grand Bénare — photo Mamphi, CC BY-SA 3.0","cadrage":"center 45%"},{"id":"r-donnees","type":"rubrique","onglet":"s-informer","ordre":3,"titre":"Vos données restent les vôtres","resume":"Où sont vos données, qui y accède, comment les récupérer. Sans petites lignes.","contenu":"\n## Elles ne servent qu’à vous\nAucune autre finalité. Aucun entraînement de modèle d’intelligence artificielle. vavang n’utilise d’ailleurs aucune IA.\n\n## Vous les récupérez quand vous voulez\nL’administrateur exporte tout en une archive : données en JSON et en CSV, documents d’origine, journaux, inventaire et dictionnaire des données. Aucun format propriétaire.\n\n## Chaque accès laisse une trace\nConnexions, échecs, changements de droits, exports : tout est inscrit au journal de sécurité, qui ne se modifie pas.\n\n> La double authentification est obligatoire pour les administrateurs.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/mafate-depuis-le-grand-benare.jpg","credit":"Mafate depuis le Grand Bénare — photo Mamphi, CC BY-SA 3.0","cadrage":"center 45%"},{"id":"r-support","type":"rubrique","onglet":"echanges","ordre":1,"titre":"Contacter le support","resume":"Une question, un blocage : déclarez votre demande dans vavang et suivez-la jusqu’à sa clôture.","contenu":"\n## Le plus rapide : la demande d’assistance\nMenu « Demandes d’assistance », puis « Nouvelle demande ». Indiquez l’écran concerné et joignez une capture si vous pouvez.\n\n## Ce que vous voyez ensuite\n- Un numéro unique.\n- La criticité, de P1 (tout est bloqué) à P4 (simple question).\n- Les délais d’intervention qui s’appliquent, et s’ils sont tenus.\n- Chaque échange, daté.\n\n## Qui clôt la demande ?\nVous. Le support propose une solution ; c’est la collectivité qui valide que le problème est réglé.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/le-port-vue-du-ciel.jpg","credit":"Le Port vu du ciel — photo Ville du Port, CC BY-SA 4.0","cadrage":"center 55%"},{"id":"r-ameliorations","type":"rubrique","onglet":"echanges","ordre":2,"titre":"Proposer une amélioration","resume":"Une fonction vous manque, un écran vous semble compliqué ? Dites-le. Chaque proposition reçoit une réponse.","contenu":"\nLes meilleures évolutions viennent de ceux qui utilisent l’outil tous les jours.\n\n## Comment proposer\nDéclarez une demande d’assistance en criticité P4, avec le mot « évolution » dans l’objet. Décrivez le besoin, pas la solution : on cherchera la bonne ensemble.\n\n> Chaque proposition reçoit une réponse argumentée : retenue, à l’étude, ou non retenue et pourquoi.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/le-port-vue-du-ciel.jpg","credit":"Le Port vu du ciel — photo Ville du Port, CC BY-SA 4.0","cadrage":"center 55%"},{"id":"r-club","type":"rubrique","onglet":"echanges","ordre":3,"titre":"Le club des utilisateurs","resume":"Des agents de plusieurs services qui partagent leurs modèles et leurs astuces. Une rencontre par trimestre.","contenu":"\n## Pourquoi un club\nUn modèle de lettre de rejet bien fait sert à tout le monde. Une astuce de paramétrage aussi.\n\n## Ce qu’on y fait\n- Des retours d’expérience, sans jargon.\n- Des modèles partagés entre services.\n- Les priorités d’évolution, votées par ceux qui utilisent l’outil.","lecture_min":1,"actif":true,"mis_a_jour":"2026-11-18","image":"img/photos/le-port-vue-du-ciel.jpg","credit":"Le Port vu du ciel — photo Ville du Port, CC BY-SA 4.0","cadrage":"center 55%"}],"fournisseurs":[{"id":"f1","raison_sociale":"Exemple Tamarin Paysage","siret":"000 000 001 00011","commune":"Commune A","domaines":"Espaces verts, élagage","taille":"PME","source":"Candidature à une consultation","actif":true,"contact":"Service commercial","email":"contact@f1.example","qualification":"Qualification professionnelle déclarée en entretien d'espaces verts ; certificat de capacité pour l'usage de produits de biocontrôle."},{"id":"f2","raison_sociale":"Exemple Vacoa Environnement","siret":"000 000 002 00012","commune":"Commune B","domaines":"Espaces verts, propreté","taille":"PME","source":"Rencontre de sourcing","actif":true,"contact":"Service commercial","email":"contact@f2.example","qualification":""},{"id":"f3","raison_sociale":"Exemple Longani Jardins","siret":"000 000 003 00013","commune":"Commune A","domaines":"Espaces verts","taille":"TPE","source":"Candidature à une consultation","actif":true,"contact":"Service commercial","email":"contact@f3.example","qualification":""},{"id":"f4","raison_sociale":"Exemple Bois-de-Rose Mobilier","siret":"000 000 004 00014","commune":"Commune C","domaines":"Mobilier de bureau","taille":"PME","source":"Salon professionnel","actif":true,"contact":"Service commercial","email":"contact@f4.example","qualification":""},{"id":"f5","raison_sociale":"Exemple Filaos Informatique","siret":"000 000 005 00015","commune":"Commune B","domaines":"Matériel et services informatiques","taille":"PME","source":"Titulaire d'un marché antérieur","actif":true,"contact":"Service commercial","email":"contact@f5.example","qualification":""},{"id":"f6","raison_sociale":"Exemple Corail Propreté","siret":"000 000 006 00016","commune":"Commune D","domaines":"Nettoyage de locaux","taille":"ESS","source":"Recommandation d'un service","actif":true,"contact":"Service commercial","email":"contact@f6.example","qualification":""}],"fournisseur_suivi":[{"id":"fs1","fournisseur_id":"f2","date":"2026-09-10","type":"Rencontre de sourcing","compte_rendu":"Présentation des moyens matériels (broyeurs, tondeuses électriques) et des capacités d'intervention sur les sites en pente. Aucune information sur la consultation à venir n'a été communiquée.","auteur_nom":"Camille Morel"}],"besoins":[{"id":"b1","reference":"B-2026-001","objet":"Entretien des espaces verts des sites communautaires","s