nducteur de travaux.\n\n3. Délais d'intervention\nIntervention sur demande sous cinq jours ouvrés.","4. Performance environnementale\nLes déchets verts sont évacués en déchetterie."],"nb_pages":3,"lisible":true,"controle":"non_controlee","version":1,"depose_par_nom":"Camille Morel","depose_le":"2026-11-08T10:12:00.000Z"},{"id":"p-o3-3","consultation_id":"c1","lot_id":"l1","offre_id":"o3","type_piece":"Bordereau de prix / DPGF","nom_fichier":"Bordereau_de_prix_DPGF_Longani.txt","chemin":"c1/demo-o3-3.txt","taille":141,"mime":"text/plain","pages":["Bordereau de prix / DPGF — Exemple Longani Jardins\nConsultation 2026-004, lot 1.\nDocument de candidature fictif établi pour la démonstration."],"nb_pages":1,"lisible":true,"controle":"non_controlee","version":1,"depose_par_nom":"Camille Morel","depose_le":"2026-11-08T10:12:00.000Z"}],"lignes_prix":[{"id":"lp-o1-0","offre_id":"o1","ordre":1,"designation":"Tonte et débroussaillage hebdomadaires","unite":"passage","quantite":52,"prix_unitaire":950,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o1-1","offre_id":"o1","ordre":2,"designation":"Taille des haies et massifs","unite":"intervention","quantite":24,"prix_unitaire":1400,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o1-2","offre_id":"o1","ordre":3,"designation":"Élagage et abattage sur demande","unite":"journée","quantite":12,"prix_unitaire":1850,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o2-0","offre_id":"o2","ordre":1,"designation":"Tonte et débroussaillage hebdomadaires","unite":"passage","quantite":52,"prix_unitaire":1100,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o2-1","offre_id":"o2","ordre":2,"designation":"Taille des haies et massifs","unite":"intervention","quantite":24,"prix_unitaire":1500,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o2-2","offre_id":"o2","ordre":3,"designation":"Élagage et abattage sur demande","unite":"journée","quantite":12,"prix_unitaire":2100,"consultation_id":"c1","lot_id":"l1"},{"id":"lp-o3-0","offre_id":"o3","ordre":1,"d