id":"l1","offre_id":"o3","type":"complement","objet":"Produire le formulaire DC2, absent du pli.","date_envoi":"2026-11-10","echeance":"2026-11-15","reponse":"DC2 transmis par le candidat.","date_reponse":"2026-11-14","statut":"reponse_recue"}],"modeles_document":[{"id":"md1","type":"dce","categorie":"Règlement de la consultation","nom":"Règlement de la consultation — procédure adaptée","contenu":"RÈGLEMENT DE LA CONSULTATION\n{{organisme}}\nConsultation {{reference}} — {{objet}}\n\nARTICLE 1 — Objet de la consultation\nLa présente consultation a pour objet : {{objet}}.\nNature des prestations : {{nature}}. Forme du marché : {{type_marche}}.\n\nARTICLE 2 — Procédure\nLa consultation est passée selon la procédure suivante : {{procedure}}.\n\nARTICLE 3 — Allotissement\n{{lots}}\n\nARTICLE 4 — Remise des offres\nLes offres sont remises par voie dématérialisée avant le {{date_limite}} à 12 h 00 (heure de La Réunion).\n\nARTICLE 5 — Critères de jugement des offres\n{{criteres}}\n\nARTICLE 6 — Renseignements complémentaires\n[à compléter : modalités de questions et de réponses]","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"md2","type":"dce","categorie":"CCAP","nom":"CCAP — services courants","contenu":"CAHIER DES CLAUSES ADMINISTRATIVES PARTICULIÈRES\n{{organisme}}\nConsultation {{reference}} — {{objet}}\n\nARTICLE 1 — Objet et forme du marché\n{{objet}}. Forme : {{type_marche}}.\n\nARTICLE 2 — Durée\n[à compléter : durée et reconductions]\n\nARTICLE 3 — Prix et règlement\nLes prix sont réputés établis sur la base des conditions économiques du mois de remise des offres. Le délai global de paiement est de trente jours.\n\nARTICLE 4 — Pénalités\n[à compléter]\n\nARTICLE 5 — Document de référence\nLe cahier des clauses administratives générales applicable est celui des marchés de fournitures courantes et de services.","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"md3","type":"dce","categorie":"Acte d'engagement","nom":"Acte d'engagement simplifié","contenu":"ACTE D'ENGAGEMENT\n{{organisme}}\nConsultation {{reference}} — {{objet}}\n\nARTICLE 1 — Contractant\n[à compléter par le candidat : dénomination, adresse, SIRET]\n\nARTICLE 2 — Prix\nMontant hors taxes : [à compléter par le candidat]\n\nARTICLE 3 — Durée\n[à compléter]\n\nARTICLE 4 — Signature\nFait à ............, le ............","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mc1","type":"clause","categorie":"CCAP","nom":"Clause de révision des prix","contenu":"Les prix sont révisables annuellement à la date anniversaire de la notification, par application de la formule : P = P0 × (0,15 + 0,85 × I / I0), où I est la dernière valeur connue de l'indice de référence et I0 sa valeur au mois d'établissement des prix.","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mc2","type":"clause","categorie":"CCAP","nom":"Clause environnementale d'exécution","contenu":"Le titulaire transmet chaque année un bilan des actions environnementales mises en œuvre dans l'exécution du marché : gestion des déchets, consommations, déplacements. Ce bilan est présenté lors de la réunion annuelle de suivi.","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mc3","type":"clause","categorie":"Règlement de la consultation","nom":"Clause sur les offres anormalement basses","contenu":"Lorsqu'une offre paraît anormalement basse, l'acheteur demande par écrit au candidat les précisions et justifications qu'il juge utiles. L'offre n'est rejetée, par décision motivée, que si les éléments fournis ne justifient pas de manière satisfaisante le bas niveau du prix.","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mk1","type":"courrier","categorie":"Demande de justification du prix","nom":"Demande de justification du prix","contenu":"{{organisme}}\nLe {{date}}\n\nObjet : consultation {{reference}} — {{objet}} — {{lot}}\nDemande de justification du prix\n\nMadame, Monsieur,\n\nVotre société, {{candidat}}, a remis une offre d'un montant de {{montant}} HT. Ce montant paraît bas au regard des autres offres reçues et de l'estimation de l'acheteur.\n\nJe vous demande de bien vouloir me transmettre, avant le [date à compléter], toute précision et justification utile sur la composition de votre prix : sous-détail des prix, temps passés, coûts de main-d'œuvre, solutions techniques retenues.\n\nÀ défaut de réponse ou si les éléments fournis ne justifient pas le niveau du prix, votre offre pourra être rejetée par décision motivée.\n\nJe vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\n\n{{agent}}","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mk2","type":"courrier","categorie":"Demande de précisions","nom":"Demande de précisions sur l'offre","contenu":"{{organisme}}\nLe {{date}}\n\nObjet : consultation {{reference}} — {{objet}} — {{lot}}\nDemande de précisions\n\nMadame, Monsieur,\n\nDans le cadre de l'analyse de l'offre remise par {{candidat}}, je vous remercie de préciser le point suivant, sans modifier votre offre : [point à préciser].\n\nVotre réponse est attendue avant le [date à compléter].\n\nJe vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\n\n{{agent}}","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mk3","type":"courrier","categorie":"Lettre de rejet","nom":"Information du candidat non retenu","contenu":"{{organisme}}\nLe {{date}}\n\nObjet : consultation {{reference}} — {{objet}} — {{lot}}\nInformation sur le rejet de votre offre\n\nMadame, Monsieur,\n\nJ'ai le regret de vous informer que l'offre de {{candidat}} n'a pas été retenue.\n\nVotre offre a obtenu la note de {{note_totale}} sur 100 et a été classée au rang {{rang}}.\nLe marché est attribué à {{attributaire}}, dont l'offre a obtenu la note de {{note_attributaire}} sur 100.\n\nMotifs détaillés : [à compléter à partir du rapport d'analyse].\n\nLe marché ne sera pas signé avant l'expiration du délai applicable à compter de l'envoi de la présente.\n\nJe vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\n\n{{agent}}","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"},{"id":"mk4","type":"courrier","categorie":"Notification","nom":"Notification du marché","contenu":"{{organisme}}\nLe {{date}}\n\nObjet : consultation {{reference}} — {{objet}} — {{lot}}\nNotification du marché\n\nMadame, Monsieur,\n\nJ'ai le plaisir de vous notifier le marché cité en objet, attribué à {{candidat}} pour un montant de {{montant}} HT.\n\nVous trouverez ci-joint l'acte d'engagement signé. L'exécution des prestations débutera à réception de l'ordre de service.\n\nJe vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\n\n{{agent}}","version":1,"actif":true,"auteur_nom":"Alix Fontaine","modifie_le":"2026-06-22T06:12:00.000Z"}],"documents_dce":[{"id":"dd1","consultation_id":"c2","type_piece":"Règlement de la consultation","titre":"Règlement de la consultation — 2026-007","contenu":"RÈGLEMENT DE LA CONSULTATION\nCommunauté d'agglomération de démonstration\nConsultation 2026-007 — Renouvellement de postes informatiques\n\nARTICLE 1 — Objet de la consultation\nLa présente consultation a pour objet : Renouvellement de postes informatiques.\nNature des prestations : Fournitures. Forme du marché : Marché ordinaire à prix forfaitaire.\n\nARTICLE 2 — Procédure\nLa consultation est passée selon la procédure suivante : Procédure adaptée (MAPA).\n\nARTICLE 3 — Allotissement\nLot 1 — Lot unique\n\nARTICLE 4 — Remise des offres\nLes offres sont remises par voie dématérialisée avant le 13/12/2026 à 12 h 00 (heure de La Réunion).\n\nARTICLE 5 — Critères de jugement des offres\n{{criteres}}\n\nARTICLE 6 — Renseignements complémentaires\n[à compléter : modalités de questions et de réponses]","version":2,"statut":"relecture","modele_id":"md1","redacteur_nom":"Camille Morel","modifie_le":"2026-11-17T11:12:00.000Z"},{"id":"dd2","consultation_id":"c2","type_piece":"CCTP","titre":"CCTP — 2026-007","contenu":"CAHIER DES CLAUSES TECHNIQUES PARTICULIÈRES\nConsultation 2026-007 — Renouvellement de postes informatiques\n\nARTICLE 1 — Objet\nFourniture de 80 postes de travail fixes et de 40 ordinateurs portables, avec leur garantie de trois ans sur site.\n\nARTICLE 2 — Caractéristiques minimales\nProcesseur récent, 16 Go de mémoire, stockage de 512 Go, écran de 24 pouces pour les postes fixes.\n\nARTICLE 3 — Livraison\nLivraison et mise en service sur les sites de l'acheteur dans un délai de six semaines à compter de la commande.\n\nARTICLE 4 — Reprise des anciens matériels\nLe titulaire reprend les matériels remplacés et justifie de leur réemploi ou de leur recyclage.","version":1,"statut":"redaction","redacteur_nom":"Sacha Leroy","modifie_le":"2026-11-15T06:12:00.000Z"}],"documents_versions":[{"id":"dv1","document_id":"dd1","consultation_id":"c2","version":1,"contenu":"RÈGLEMENT DE LA CONSULTATION\n{{organisme}}\nConsultation {{reference}} — {{objet}}\n\nARTICLE 1 — Objet de la consultation\nLa présente consultation a pour objet : {{objet}}.\nNature des prestations : {{nature}}. Forme du marché : {{type_marche}}.\n\nARTICLE 2 — Procédure\nLa consultation est passée selon la procédure suivante : {{procedure}}.\n\nARTICLE 3 — Allotissement\n{{lots}}\n\nARTICLE 4 — Remise des offres\nLes offres sont remises par voie dématérialisée avant le {{date_limite}} à 12 h 00 (heure de La Réunion).\n\nARTICLE 5 — Critères de jugement des offres\n{{criteres}}\n\nARTICLE 6 — Renseignements complémentaires\n[à compléter : modalités de questions et de réponses]","auteur_nom":"Camille Morel","date":"2026-11-14T05:12:00.000Z","commentaire":"Création depuis le modèle « Règlement de la consultation — procédure adaptée » version 1"},{"id":"dv2","document_id":"dd1","consultation_id":"c2","version":2,"contenu":"RÈGLEMENT DE LA CONSULTATION\nCommunauté d'agglomération de démonstration\nConsultation 2026-007 — Renouvellement de postes informatiques\n\nARTICLE 1 — Objet de la consultation\nLa présente consultation a pour objet : Renouvellement de postes informatiques.\nNature des prestations : Fournitures. Forme du marché : Marché ordinaire à prix forfaitaire.\n\nARTICLE 2 — Procédure\nLa consultation est passée selon la procédure suivante : Procédure adaptée (MAPA).\n\nARTICLE 3 — Allotissement\nLot 1 — Lot unique\n\nARTICLE 4 — Remise des offres\nLes offres sont remises par voie dématérialisée avant le 13/12/2026 à 12 h 00 (heure de La Réunion).\n\nARTICLE 5 — Critères de jugement des offres\n{{criteres}}\n\nARTICLE 6 — Renseignements complémentaires\n[à compléter : modalités de questions et de réponses]","auteur_nom":"Camille Morel","date":"2026-11-17T11:12:00.000Z","commentaire":"Renseignement des données de la consultation"},{"id":"dv3","document_id":"dd2","consultation_id":"c2","version":1,"contenu":"CAHIER DES CLAUSES TECHNIQUES PARTICULIÈRES\nConsultation 2026-007 — Renouvellement de postes informatiques\n\nARTICLE 1 — Objet\nFourniture de 80 postes de travail fixes et de 40 ordinateurs portables, avec leur garantie de trois ans sur site.\n\nARTICLE 2 — Caractéristiques minimales\nProcesseur récent, 16 Go de mémoire, stockage de 512 Go, écran de 24 pouces pour les postes fixes.\n\nARTICLE 3 — Livraison\nLivraison et mise en service sur les sites de l'acheteur dans un délai de six semaines à compter de la commande.\n\nARTICLE 4 — Reprise des anciens matériels\nLe titulaire reprend les matériels remplacés et justifie de leur réemploi ou de leur recyclage.","auteur_nom":"Sacha Leroy","date":"2026-11-15T06:12:00.000Z","commentaire":"Création"}],"validations":[{"id":"va1","objet_type":"docu